import { unstable_cache, revalidateTag } from 'next/cache';
import { getAllProducts } from '@/lib/db';

// Cache the product data fetching
const getCachedProducts = unstable_cache(
  async () => {
    return await getAllProducts();
  },
  ['products-list'], // Cache key
  { tags: ['products'] } // Tags for invalidation
);

export default async function Page() {
  const products = await getCachedProducts();

  // Server Action to invalidate the cache
  async function syncCatalog() {
    'use server';
    // Invalidate the cache tag 'products'
    // This will cause the next request (or background revalidation) to fetch fresh data
    revalidateTag('products');
  }

  return (
    <div className="min-h-screen bg-gray-50 p-8 font-sans">
      <div className="max-w-7xl mx-auto">
        <header className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Product Catalog</h1>
            <p className="text-gray-500 mt-2">Manage your product inventory</p>
          </div>

          <form action={syncCatalog}>
            <button 
              type="submit"
              className="bg-black hover:bg-gray-800 text-white font-medium py-2 px-6 rounded-md transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-black"
            >
              Sync Latest Catalog
            </button>
          </form>
        </header>

        <main>
          <div className="bg-white shadow overflow-hidden sm:rounded-md">
            <ul role="list" className="divide-y divide-gray-200">
              {products.map((product: any) => (
                <li key={product.id}>
                  <div className="px-4 py-4 sm:px-6 hover:bg-gray-50 transition-colors">
                    <div className="flex items-center justify-between">
                      <p className="text-sm font-medium text-indigo-600 truncate">{product.name}</p>
                      <div className="ml-2 flex-shrink-0 flex">
                        <p className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-green-100 text-green-800">
                          In Stock: {product.stock}
                        </p>
                      </div>
                    </div>
                    <div className="mt-2 sm:flex sm:justify-between">
                      <div className="sm:flex">
                        <p className="flex items-center text-sm text-gray-500">
                          ID: {product.id}
                        </p>
                      </div>
                      <div className="mt-2 flex items-center text-sm text-gray-500 sm:mt-0">
                        <p>
                          Price: <span className="font-medium text-gray-900">${product.price}</span>
                        </p>
                      </div>
                    </div>
                  </div>
                </li>
              ))}
            </ul>
          </div>
        </main>

        <footer className="mt-8 text-center text-sm text-gray-500">
          <p>Data is cached. Use "Sync Latest Catalog" to refresh.</p>
        </footer>
      </div>
    </div>
  );
}

