                <h2 style={{ fontSize: '1.25rem', fontWeight: '600', margin: 0, color: '#111' }}>{product.name}</h2>
                <span style={{ 
                  fontSize: '0.75rem', 
                  backgroundColor: '#dcfce7', 
                  color: '#166534', 
                  padding: '0.25rem 0.75rem', 
                  borderRadius: '9999px',
                  fontWeight: '500'
                }}>
                  In Stock: {product.stock}
                </span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderTop: '1px solid #f3f4f6', paddingTop: '1rem', marginTop: '1rem' }}>
                <span style={{ color: '#6b7280', fontSize: '0.875rem' }}>ID: {product.id}</span>
                <span style={{ fontSize: '1.125rem', fontWeight: '700', color: '#111' }}>${product.price}</span>
              </div>
            </div>
          ))}
        </div>
      </main>

      <footer style={{ marginTop: '3rem', textAlign: 'center', color: '#9ca3af', fontSize: '0.875rem', borderTop: '1px solid #eee', paddingTop: '1.5rem' }}>
        <p>Catalog data is cached. Syncing invalidates the cache.</p>
      </footer>
    </div>
  );
}

